async Task<T> Run<T>(UserMembership m,Func<IServiceProvider,Task<T>> operation){accessor.HttpContext=new DefaultHttpContext();accessor.HttpContext.User=new ClaimsPrincipal(new ClaimsIdentity(new[]{new Claim(ClaimTypes.NameIdentifier,m.UserId.ToString()),new Claim("UserMembershipId",m.UserMembershipId.ToString()),new Claim("FarmHouseId",m.FarmHouseId.ToString()),new Claim(ClaimTypes.Role,m.RoleId==adminRole.RoleId?"Admin":m.RoleId==ownerRole.RoleId?"Farm Owner":"Customer")},"fixture"));accessor.HttpContext.Request.Headers["FarmHouseId"]=m.FarmHouseId.ToString();await using var scope=provider.CreateAsyncScope();return await operation(scope.ServiceProvider);}
async Task<SubmitBookingRequest> Request(UserMembership actor,User customer,DateTime date,bool expired=false){var quote=await Run(actor,async s=>(await s.GetRequiredService<IFarmHousePricingService>().GetQuoteAsync(new(DateOnly.FromDateTime(date),DateOnly.FromDateTime(date.AddDays(1)),"BookingOnly",[]))).Data!);Check(quote!=null,"Missing quote");var hold=new BookingDateReservation{FarmHouseId=farm.FarmHouseId,UserId=actor.UserId,SelectionId=Guid.NewGuid(),ReservationDate=date,ExpiresAt=DateTime.Now.AddMinutes(expired?-1:10)};db.Add(hold);await db.SaveChangesAsync();return new(hold.SelectionId,[hold.ReservationId],customer.FullName,customer.MobileNumber,null,DateOnly.FromDateTime(date),DateOnly.FromDateTime(date.AddDays(1)),"BookingOnly",[],1,0,1,null,Guid.NewGuid(),quote.PricingVersion);}
Task<BookingSubmissionResult> Submit(UserMembership m,SubmitBookingRequest r)=>Run(m,s=>s.GetRequiredService<IBookingSubmission>().SubmitAsync(m.FarmHouseId,m.UserId,r,default));
