sealed class FixedContext:IHttpContextAccessor{public HttpContext? HttpContext{get;set;}}
sealed class FixtureGateway:IHttpClientFactory {
 public string Variant="valid";public int Calls;
 public HttpClient CreateClient(string name)=>new(new FixtureHandler(this)){BaseAddress=new Uri("https://fixture.invalid/v1/")};
 sealed class FixtureHandler(FixtureGateway fixture):HttpMessageHandler {
  protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken ct){fixture.Calls++;if(fixture.Variant=="error")return Task.FromResult(new HttpResponseMessage(System.Net.HttpStatusCode.ServiceUnavailable));var json=JsonSerializer.Serialize(new{items=new[]{new{id="pay_fixture",status=fixture.Variant=="pending"?"authorized":"captured",captured=fixture.Variant!="pending",order_id=fixture.Variant=="order"?"order_wrong":"order_fixture",amount=fixture.Variant=="amount"?1:100000,currency=fixture.Variant=="currency"?"USD":"INR",amount_refunded=fixture.Variant=="refunded"?1:0}}});return Task.FromResult(new HttpResponseMessage(System.Net.HttpStatusCode.OK){Content=new StringContent(json,Encoding.UTF8,"application/json")});}
 }
